contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2) public {
        require(address(c) != address(0));

        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        bool firstReverted;
        c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(v2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            (!firstReverted && afterFirst == v1 && !secondReverted && afterSecond == v2)
            ||
            (!firstReverted && afterFirst == v1 && secondReverted && afterSecond == v1)
        );
    }

    receive() external payable {}
}

