pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v1, uint256 v2) internal {
        vm.assume(address(c) != address(0));
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        bool firstReverted;
        try c.SetMinSum(v1) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        bool secondReverted;
        try c.SetMinSum(v2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        assertTrue((!firstReverted && afterFirst == v1 && !secondReverted && afterSecond == v2)
            ||
            (!firstReverted && afterFirst == v1 && secondReverted && afterSecond == v1));
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
